\fill (0,0) circle (3pt);
\node[below left] at (0,0) {$O$};
\fill (5,0) circle (3pt);
\node[below right] at (5,0) {$5$};
\fill (-5,0) circle (3pt);
\node[below left] at (-5,0) {$-5$};
\fill (0,5) circle (3pt);
\node[above left] at (0,5) {$5$};
\fill (0,-5) circle (3pt);
\node[below right] at (0,-5) {$-5$};
\end{tikzpicture}
[/tikz]

